import json
import os
from datetime import datetime, timezone
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse


class VendorSyncHandler(BaseHTTPRequestHandler):
    """Request handler wired to Store and MeridianClient."""

    # Injected at runtime by serve()
    store = None  # type: ignore
    client = None  # type: ignore

    def log_message(self, format, *args):  # noqa: A002
        """Suppress default request logging for cleanliness."""

    def _send_json(self, status: int, data: dict | list) -> None:
        body = json.dumps(data, indent=2).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _send_html(self, status: int, html: str) -> None:
        body = html.encode()
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _read_json_body(self) -> dict | None:
        length = int(self.headers.get("Content-Length", 0))
        if length == 0:
            return None
        raw = self.rfile.read(length)
        return json.loads(raw)

    def do_GET(self):
        path = urlparse(self.path).path

        if path == "/health":
            self._handle_health()
        elif path == "/payments":
            self._handle_payments_list()
        elif path == "/summary":
            self._handle_summary()
        elif path == "/web" or path == "/web/":
            self._serve_index()
        else:
            self._send_json(404, {"error": "not found"})

    def do_POST(self):
        path = urlparse(self.path).path

        if path == "/sync":
            self._handle_sync()
        elif path == "/payments":
            self._handle_payment_create()
        else:
            self._send_json(404, {"error": "not found"})

    # --- route handlers -------------------------------------------------------

    def _handle_health(self):
        last = self.store.last_sync()
        self._send_json(200, {
            "status": "ok",
            "last_sync": last,
        })

    def _handle_payments_list(self):
        payments = self.store.all_payments()
        self._send_json(200, {
            "count": len(payments),
            "payments": payments,
        })

    def _handle_summary(self):
        payments = self.store.all_payments()

        total_minor = 0
        currencies: dict[str, int] = {}

        for p in payments:
            amt = p["amount_minor"]
            cur = p["currency"]
            total_minor += amt
            currencies[cur] = currencies.get(cur, 0) + amt

        self._send_json(200, {
            "count": len(payments),
            "total_minor_units": total_minor,
            "currencies": currencies,
        })

    def _handle_sync(self):
        try:
            payments = self.client.fetch_all_payments()
            inserted = self.store.upsert_many(payments)
            now = datetime.now(timezone.utc).isoformat()
            self.store.set_last_sync(now)
            self._send_json(200, {
                "synced": True,
                "fetched": len(payments),
                "upserted": inserted,
                "last_sync": now,
            })
        except Exception as e:
            self._send_json(500, {"error": str(e)})

    def _handle_payment_create(self):
        try:
            body = self._read_json_body()
            if not body or "amount_minor" not in body or "currency" not in body or "idempotency_key" not in body:
                self._send_json(400, {"error": "missing amount_minor, currency, or idempotency_key"})
                return

            payment_id = self.client.create_payment(
                amount_minor=body["amount_minor"],
                currency=body["currency"],
                idempotency_key=body["idempotency_key"],
            )
            self._send_json(201, {"id": payment_id})
        except Exception as e:
            code = 500
            if "409" in str(e):
                code = 409
            self._send_json(code, {"error": str(e)})

    # --- static ---------------------------------------------------------------

    def _serve_index(self):
        web_dir = os.path.join(os.path.dirname(__file__), "web")
        index_path = os.path.join(web_dir, "index.html")
        try:
            with open(index_path, "r", encoding="utf-8") as f:
                html = f.read()
            self._send_html(200, html)
        except FileNotFoundError:
            self._send_json(404, {"error": "index.html not found"})


def serve(port: int, store, client) -> None:
    """Start JSON API + frontend server on 127.0.0.1:port and block until shutdown."""
    VendorSyncHandler.store = store
    VendorSyncHandler.client = client

    server = HTTPServer(("127.0.0.1", port), VendorSyncHandler)
    print(f"vendorsync listening on http://127.0.0.1:{port}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nShutting down.")
        server.shutdown()
